package com.univmar.rfq.domain;
import com.univmar.customer.domain.CustomerProject; import com.univmar.shared.domain.BaseEntity; import com.univmar.user.domain.User; import jakarta.persistence.*; import java.time.LocalDate;
@Entity @Table(name="quote_requests") public class QuoteRequest extends BaseEntity {
 @ManyToOne(optional=false) @JoinColumn(name="customer_id") private User customer; @ManyToOne @JoinColumn(name="project_id") private CustomerProject project; @Enumerated(EnumType.STRING) @Column(nullable=false) private RfqStatus status=RfqStatus.DRAFT; private String notes; private LocalDate desiredDate; private Long assigneeId;
 protected QuoteRequest(){} public QuoteRequest(User customer,String notes,LocalDate desiredDate){this(customer,null,notes,desiredDate);} public QuoteRequest(User customer,CustomerProject project,String notes,LocalDate desiredDate){this.customer=customer;this.project=project;this.notes=notes;this.desiredDate=desiredDate;}
 public User getCustomer(){return customer;} public CustomerProject getProject(){return project;} public RfqStatus getStatus(){return status;} public String getNotes(){return notes;} public LocalDate getDesiredDate(){return desiredDate;} public Long getAssigneeId(){return assigneeId;} public void submit(){if(status!=RfqStatus.DRAFT)throw new IllegalStateException("RFQ is not a draft");status=RfqStatus.SUBMITTED;} public void review(Long assignee){if(status!=RfqStatus.SUBMITTED)throw new IllegalStateException("RFQ cannot be reviewed");status=RfqStatus.UNDER_REVIEW;assigneeId=assignee;} public void quoted(){if(status!=RfqStatus.UNDER_REVIEW&&status!=RfqStatus.QUOTED)throw new IllegalStateException("RFQ must be under review before it can be quoted");status=RfqStatus.QUOTED;}
}
